window.RP_SESSION={"id":"S-e957e5c46568","messages":[{"id":"RP-III-0155064","time":"2026-08-21T02:35:00+09:00","room":"RP III","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"슈욱","characters":["P-fec1db60d51e"]},{"id":"RP-III-0155065","time":"2026-08-21T02:35:00+09:00","room":"RP III","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"!민첩","characters":["P-fec1db60d51e"]},{"id":"RP-III-0155066","time":"2026-08-21T02:35:00+09:00","room":"RP III","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"'레마 캐롤라인'의 민첩 판정 :\n[9] + [3] = [12]\n결과 : 완벽한 성공, 운명은 당신의 편입니다.","characters":[]},{"id":"RP-III-0155067","time":"2026-08-21T02:35:00+09:00","room":"RP III","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"팍","characters":["P-fec1db60d51e"]},{"id":"RP-III-0155068","time":"2026-08-21T02:35:00+09:00","room":"RP III","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"오늘도 불쌍한 표적지에는 화살이 꽂힌다.","characters":["P-fec1db60d51e"]},{"id":"RP-III-0155069","time":"2026-08-21T02:36:00+09:00","room":"RP III","name":"조니","profile":"조니","identity":"reviewed","type":"dialogue","body":"\" 레마씨? 또 활을 연습하고 계셨군요. 오랜만입니다. \"","characters":["P-8b864b607de4"]},{"id":"RP-III-0155070","time":"2026-08-21T02:36:00+09:00","room":"RP III","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"레마는 빈 화살통을 들고 손수건으로 땀을 닦으며 표적지를 정리하러 다가서는데...","characters":["P-fec1db60d51e"]},{"id":"RP-III-0155071","time":"2026-08-21T02:36:00+09:00","room":"RP III","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"\" 조니 씨, 이, 이게 얼마만에요! 그동안 어, 어디 계셨어요? \"","characters":["P-fec1db60d51e"]},{"id":"RP-III-0155072","time":"2026-08-21T02:37:00+09:00","room":"RP III","name":"조니","profile":"조니","identity":"reviewed","type":"dialogue","body":"\" 아... 그러게요. 요새 참 이것저것 신경쓸 것들이 있어서... 자주 못 뵈었네요. \"","characters":["P-8b864b607de4"]},{"id":"RP-III-0155073","time":"2026-08-21T02:40:00+09:00","room":"RP III","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"일단 조니를 끌어안고 등을 탕탕 두드리고.","characters":["P-fec1db60d51e"]},{"id":"RP-III-0155074","time":"2026-08-21T02:40:00+09:00","room":"RP III","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"\" 자, 자주 와요. \"","characters":["P-fec1db60d51e"]},{"id":"RP-III-0155075","time":"2026-08-21T02:42:00+09:00","room":"RP III","name":"조니","profile":"조니","identity":"reviewed","type":"dialogue","body":"등에 전해진 충격에 무의식적으로 약간 굽어있던 허리가 곧게 펴집니다.\n\n\" 하하... 마음같아선 그러고 싶네요... \"","characters":["P-8b864b607de4"]},{"id":"RP-III-0155076","time":"2026-08-21T02:43:00+09:00","room":"RP III","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"\" 뭐, 자, 장기 의뢰라면 그럴 수 이, 있죠. \"\n\n조니를 놓아주고.\n\n\" 활 쏘는 소리 드, 듣고 저 보러 오, 오신거에요? 하하! \"","characters":["P-fec1db60d51e"]},{"id":"RP-III-0155077","time":"2026-08-21T02:47:00+09:00","room":"RP III","name":"조니","profile":"조니","identity":"reviewed","type":"dialogue","body":"\" 아... 밤에 화살 날아가는 소리를 듣자니 레마씨가 아닌가 해서... \"\n\n검지로 머리를 살짝 긁으며 왜인지 살짝 눈치를 봅니다.\n\n\" 워낙 밤마다 활을 쏘시잖아요? 그런 의미의 말이었습니다.  \"","characters":["P-8b864b607de4"]},{"id":"RP-III-0155078","time":"2026-08-21T02:49:00+09:00","room":"RP III","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"\" 푸하하, 제 해, 행동 패턴을 읽혀 버, 버렸네요. 실력 안 노, 녹슬었는지 한 번 볼까요? \"\n\n조니에게 나무로 만든 대련용 가검을 주고 자기도 하나 들며.\n\n\" 몸은 푸, 풀고 왔죠? \"","characters":["P-fec1db60d51e"]},{"id":"RP-III-0155079","time":"2026-08-21T02:52:00+09:00","room":"RP III","name":"조니","profile":"조니","identity":"reviewed","type":"dialogue","body":"\" 이것 참... 피곤한 일을 마치고 오자마자 대련이라니요. \"\n\n투덜대면서도 그리웠다는 듯 은은한 미소가 번지며 가검을 받아 듭니다.\n\n\" 아마도... 마지막은 제가 이겼죠? \"\n\n도발하며 얼굴에 드러난 표정이 미소에서 웃음으로 번집니다.","characters":["P-8b864b607de4"]},{"id":"RP-III-0155080","time":"2026-08-21T03:03:00+09:00","room":"RP III","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"\" 그 우, 웃음 때문에 진짜 다시는 아, 안 질거에요. \"\n\n가검을 들고 자세를 취하더니...","characters":["P-fec1db60d51e"]},{"id":"RP-III-0155081","time":"2026-08-21T03:03:00+09:00","room":"RP III","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"!격투","characters":["P-fec1db60d51e"]},{"id":"RP-III-0155082","time":"2026-08-21T03:03:00+09:00","room":"RP III","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"'레마 캐롤라인'의 격투 판정 :\n[2, 5, 5] + [2, 5]\n성공수 : [ 3 ]","characters":[]},{"id":"RP-III-0155083","time":"2026-08-21T03:04:00+09:00","room":"RP III","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"왼발 스텝을 밟는 척 페인트를 넣고 오른발을 빠르게 앞으로 미끄러트려 거리 계산을 부수고 긴 찌르기를 넣는 레마!","characters":["P-fec1db60d51e"]},{"id":"RP-III-0155084","time":"2026-08-21T03:50:00+09:00","room":"RP III","name":"조니","profile":"조니","identity":"reviewed","type":"dialogue","body":"가검을 몸 가운데로 들고 중심을 지킨 채 앞발에 약간의 무게중심을 싫어 흘리려 합니다.","characters":["P-8b864b607de4"]},{"id":"RP-III-0155085","time":"2026-08-21T03:50:00+09:00","room":"RP III","name":"조니","profile":"조니","identity":"reviewed","type":"dialogue","body":"!격투","characters":["P-8b864b607de4"]},{"id":"RP-III-0155086","time":"2026-08-21T03:50:00+09:00","room":"RP III","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"'조니'의 격투 판정 :\n[6, 2, 6] + [2, 2]\n성공수 : [ 2 ]","characters":[]},{"id":"RP-III-0155087","time":"2026-08-21T03:53:00+09:00","room":"RP III","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"조니보다 한 발 빨랐던 레마!","characters":["P-fec1db60d51e"]},{"id":"RP-III-0155088","time":"2026-08-21T03:53:00+09:00","room":"RP III","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"레마의 가검 끝이 조니의 가슴팍 바로 앞에서 멈춘다.","characters":["P-fec1db60d51e"]},{"id":"RP-III-0155089","time":"2026-08-21T03:54:00+09:00","room":"RP III","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"\" 후후, 이제 다, 다시는 안 질 거라고 해, 했죠! \"","characters":["P-fec1db60d51e"]},{"id":"RP-III-0155090","time":"2026-08-21T03:54:00+09:00","room":"RP III","name":"조니","profile":"조니","identity":"reviewed","type":"dialogue","body":"\" 아직 안 닿았잖아요? 해적의 방식대로. 진짜로 끝날때까지. \"\n\n기습으로 허리를 향해 타격!","characters":["P-8b864b607de4"]},{"id":"RP-III-0155091","time":"2026-08-21T03:55:00+09:00","room":"RP III","name":"조니","profile":"조니","identity":"reviewed","type":"dialogue","body":"!격투","characters":["P-8b864b607de4"]},{"id":"RP-III-0155092","time":"2026-08-21T03:55:00+09:00","room":"RP III","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"'조니'의 격투 판정 :\n[2, 3, 4] + [2, 2]\n성공수 : [ 1 ]","characters":[]},{"id":"RP-III-0155093","time":"2026-08-21T03:55:00+09:00","room":"RP III","name":"조니","profile":"조니","identity":"reviewed","type":"dialogue","body":"아","characters":["P-8b864b607de4"]},{"id":"RP-III-0155094","time":"2026-08-21T04:21:00+09:00","room":"RP III","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"후후","characters":["P-fec1db60d51e"]},{"id":"RP-III-0155095","time":"2026-08-21T04:21:00+09:00","room":"RP III","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"!격투","characters":["P-fec1db60d51e"]},{"id":"RP-III-0155096","time":"2026-08-21T04:21:00+09:00","room":"RP III","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"'레마 캐롤라인'의 격투 판정 :\n[5, 2, 1] + [5, 6]\n성공수 : [ 3 ]","characters":[]},{"id":"RP-III-0155097","time":"2026-08-21T04:22:00+09:00","room":"RP III","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"\" 그, 그래봤자 안돼요! \"\n\n기습까지 가검으로 쳐내고 조니의 가슴팍에 옆차기를 날린다.","characters":["P-fec1db60d51e"]},{"id":"RP-III-0155098","time":"2026-08-21T04:23:00+09:00","room":"RP III","name":"조니","profile":"조니","identity":"reviewed","type":"dialogue","body":"\" 칫... \"\n\n옆구리를 움켜쥔채 약간의 억울함이 담긴 한숨을 푹 내쉽니다.\n\n\" 못 본 사이에 많이 강해지셨군요 레마씨. \"","characters":["P-8b864b607de4"]},{"id":"RP-III-0155099","time":"2026-08-21T04:24:00+09:00","room":"RP III","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"\" 후후, 조니 씨가 야, 약해진거 아니에요? 고기라도 좀 머, 먹여 드릴까요? \"","characters":["P-fec1db60d51e"]},{"id":"RP-III-0155100","time":"2026-08-21T04:28:00+09:00","room":"RP III","name":"조니","profile":"조니","identity":"reviewed","type":"dialogue","body":"\" 이것 참... 피곤하다 보니 잠시 실수한 것뿐, 원래였으면 제가 이깁니다. \"\n\n팔 소매로 땀방울이 흘러내리는 턱을 쓱하고 비벼 닦아내고는 가검을 세워놓습니다\n\n\" 그러고보니 레마씨 요리를 안 먹은지 오래 됐넉요. \"","characters":["P-8b864b607de4"]},{"id":"RP-III-0155101","time":"2026-08-21T04:30:00+09:00","room":"RP III","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"\" 원래도 이, 이기던게 저잖아요! \"\n\n어깨를 으쓱하며 의기양양하게 웃는다.\n\n\" 마침 활쏘기 끄, 끝나고 구워 먹으려고 야, 양념에 재워둔 돼지고기가 있는데 가, 같이 드실래요? \"","characters":["P-fec1db60d51e"]},{"id":"RP-III-0155102","time":"2026-08-21T04:32:00+09:00","room":"RP III","name":"조니","profile":"조니","identity":"reviewed","type":"dialogue","body":"\" 아, 아무튼간에 말이죠. 바다 위라면 제가 이깁니다. \"\n\n레마의 말따윈 가볍게 무시하고 도도하게 땀을 닦아냅니다.\n\n\" 레마씨는 요리를 잘 하시니까요. 좋죠. 오랜만에 둘이서 술이나 할까요? \"","characters":["P-8b864b607de4"]},{"id":"RP-III-0155103","time":"2026-08-21T04:34:00+09:00","room":"RP III","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"\" 수, 술도 좋죠! 마침 매, 맥주가 땡기던 참이었어요. \"\n\n레마가 수다를 떨며 주방으로 걸어간다. 주방에서는 보울에서 와인 비네거에 소금과 다진 마늘, 리크, 각종 허브와 으깬 펜넬 시드를 넣어 재워둔 양념 고기를 꺼낸다.\n\n\" 지하에서 빵이랑 매, 맥주 좀 가져와 줘요. 이거 굽고 이, 있을게요! \"","characters":["P-fec1db60d51e"]},{"id":"RP-III-0155104","time":"2026-08-21T04:38:00+09:00","room":"RP III","name":"조니","profile":"조니","identity":"reviewed","type":"dialogue","body":"\" 아, 알겠습니다. 그럼... \"\n\n조니는 지하로 내려가 빵과 맥주를 찾아온다.\n\n\" 요리하는 레마씨의 모습도... 참 감회가 새롭군요. \"\n\n무언가 복잡하고 미묘한 느낌이 든다.","characters":["P-8b864b607de4"]},{"id":"RP-III-0155105","time":"2026-08-21T04:40:00+09:00","room":"RP III","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"\" 그렇게까지 오, 오래됐나요? \"\n\n칼로 덩어리 상태인 고기를 탕탕 내리쳐서 잘라내고 자른 고기 위에 한 번 더 소금을 뿌려 간의 디테일을 맞춘다.\n\n\" 일단 매, 맥주 마시면서 얘기하죠. 굽는 동안 하, 한 잔 줘 봐요. \"\n\n기분 좋게 웃으면서 불에 올린 팬에 고기를 얹는다. 치이익 하는 비 같은 소리와 함께 향긋한 향기가 주변 가득 퍼진다.","characters":["P-fec1db60d51e"]},{"id":"RP-III-0155106","time":"2026-08-21T04:47:00+09:00","room":"RP III","name":"조니","profile":"조니","identity":"reviewed","type":"dialogue","body":"\" 글쎄요... 왜인지 좀... 그런 느낌이네요. \"\n\n맥주를 마시며 기분좋게 미소를 짓는다. 이 나른하고 편안한 순간이 계속되었으면 좋겠다는 생각이 들 정도로, 요리의 향기와 맥주의 씁쓸 고소한 맛이 느껴지는 상황이 기분을 좋게 만들었다.\n\n\" 역시 고기냄새는 좋네요. 벌써 침이 고이는 느낌이에요. \"\n\n고기가 익는 냄새를 맡으며 다시 한 번 맥주를 들이키고는 눈을 감고 소금기 섞인 냄새를 조용히 느낀다.","characters":["P-8b864b607de4"]},{"id":"RP-III-0155107","time":"2026-08-21T04:49:00+09:00","room":"RP III","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"\" 제가 구운 고, 고기니까 맛있는거죠. \"\n\n조니가 따라준 맥주를 한 모금 들이킨다.\n\n\" 카하. \"\n\n뭐가 묻지도 않았는데 습관적으로 입가를 슥 닦고 웃으면서. 고기 아래쪽이 갈색으로 색이 나는 것을 보고 뒤집으며.\n\n\" 고소하고 햐, 향긋하니 좋네요. 역시 밤에 마, 마시는 맥주가 최고에요. 조니 씨도 이 시, 시간까지 안 주무시는걸 보니 밤에 이, 일을 많이 하다 오셨나봐요? \"","characters":["P-fec1db60d51e"]},{"id":"RP-III-0155108","time":"2026-08-21T04:54:00+09:00","room":"RP III","name":"조니","profile":"조니","identity":"reviewed","type":"dialogue","body":"\" 그럴지도 모르죠. \"\n\n레마의 자신감 넘치는 대답에 어이없기도 하면서 재밌었기에 웃음이 터진다.\n\n\" 아무래도 최근에 무언가 복잡해져서요. 레마씨는 요즘 어떠세요? \"\n\n 레마가 들이키는 것을 보자 따라 다시 한 번 들이키고는 웃습니다.\n\n\" 어찌보면 해적의 운명인 셈이죠. \"","characters":["P-8b864b607de4"]},{"id":"RP-III-0155109","time":"2026-08-21T04:57:00+09:00","room":"RP III","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"\" 뭐야, 나 어, 없는 틈에 어디서 뭘 하고 도, 돌아다닌거에요. \"\n\n그닥 많지 않은 친구 중 하나인 조니가 자기 말고 다른데서만 놀다 와서 삐진건지, 질투라도 하는건지.\n\n\" 저야 뭐, 요새도 다, 단기 의뢰 다니고, 열심히 화, 활 연습도 하고, 검도 수, 수련하고 했죠. 요리도 마, 많이 하구요. \"\n\n적당히 구워진 고기를 팬에서 꺼내 접시에 담는다. 다음 고기들을 다시 팬에 넣자 또다시 치이익 소리가 나기 시작한다.\n\n\" 그래도 오, 오해는 마요. 이렇게 고기만 구, 구워 먹는건 꽤나 오, 오랜만이거든요. 돈이 어, 없어서... \"","characters":["P-fec1db60d51e"]},{"id":"RP-III-0155110","time":"2026-08-21T05:04:00+09:00","room":"RP III","name":"조니","profile":"조니","identity":"reviewed","type":"dialogue","body":"\" 하하... 딱히 돌아다닌 것도 아니지만요. \"\n\n씁쓸히 웃으며 다시 맥주를 들이킵니다.\n\n\" 단기의뢰에 수련까지... 이거 부끄러워지내요. 빨리 해결하고 따라 잡아야하는데 말이죠. \"\n\n표정에 그림자가 짙어집니다.\n\n\" 하하, 쓸데없는 얘기를 됐고... 건배 하실래요? \"\n\n술잔을 내밉니다.\n\n\" 뭐든간에, 힘냅시다. \"","characters":["P-8b864b607de4"]},{"id":"RP-III-0155111","time":"2026-08-21T05:06:00+09:00","room":"RP III","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"\" 거, 건배! \"\n\n또 술잔에 술잔을 부딪히고 한 모금 더 크게 마신다. 고기가 잘 구워지자 다 꺼내서 접시에 얹어 둔다.\n\n\" 먹자구요, 부, 분명 맛있을거에요! \"\n\n레마가 고기 한 점을 포크로 집어서 입에 쏙 넣고 씹는다.\n\n\" 음, 자, 잡내 없고 맛 좋네요. \"","characters":["P-fec1db60d51e"]},{"id":"RP-III-0155112","time":"2026-08-21T05:10:00+09:00","room":"RP III","name":"조니","profile":"조니","identity":"reviewed","type":"dialogue","body":"고기를 집어 입 안에 밀어 넣자 잘 구워진 뜨끈한 육즙이 퍼지며 실한 고기의 질감이 입 안을 채운다.\n\n\" 역시 레마씨는 요리를 잘 하시네요. 맥주에 먹으니 고기맛이 더 살아나는 것 같기도... \"\n\n질겅질겅 씹으며 맥주를 들이킵니다.\n\n\" 소금을 넣어서 그런가 짭짤한 맛도 있어서 마음에 드네요. \"","characters":["P-8b864b607de4"]},{"id":"RP-III-0155113","time":"2026-08-21T05:14:00+09:00","room":"RP III","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"그렇게 두 사람이 실컷 먹고 마시며 그간 못 나눈 얘기를 풀어내는 밤이 깊어가고...","characters":["P-fec1db60d51e"]},{"id":"RP-III-0155114","time":"2026-08-21T05:14:00+09:00","room":"RP III","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"-fin","characters":["P-fec1db60d51e"]},{"id":"RP-III-0155115","time":"2026-08-21T05:15:00+09:00","room":"RP III","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"...다음 시간에.","characters":[]}]};
